import 'package:dartz/dartz.dart';import '../../../../../../Core/Models/cart_itemes.dart';import '../../../../../../Core/Storage/Remote/api_error_handler.dart';import '../repositories/cart_repo_impl.dart';class GetCartUseCase {  CartRepoImpl cartRepoImpl;  GetCartUseCase(this.cartRepoImpl);  Future<Either<Failure, CartItemsModel>> call() async =>      await cartRepoImpl.getOrders();}class UpdateCartUseCase {  CartRepoImpl cartRepoImpl;  UpdateCartUseCase(this.cartRepoImpl);  Future<Either<Failure, CartItemsModel>> call(          {required int id, required int newQuantity}) async =>      await cartRepoImpl.updateFromCart(id: id, newQuantity: newQuantity);}class RemoveItemUseCase {  CartRepoImpl cartRepoImpl;  RemoveItemUseCase(this.cartRepoImpl);  Future<Either<Failure, CartItemsModel>> call({required int id}) async =>      await cartRepoImpl.removeFromCart(id: id);}